using System;using System.Linq;using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud07Popups{public static string Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();return new JArray(h.Layout.FloatingPanels.SelectMany(p=>p.GetComponentsInChildren<RectTransform>(true)).Select(r=>new JObject{{"name",r.name},{"parent",r.parent.name},{"rect",r.rect.ToString()},{"pos",r.anchoredPosition.ToString()},{"anchors",r.anchorMin+"/"+r.anchorMax},{"layout",r.GetComponent<UnityEngine.UI.LayoutElement>()?.preferredHeight},{"scroll",r.GetComponent<UnityEngine.UI.ScrollRect>()?.viewport?.name},{"mask",r.GetComponent<UnityEngine.UI.RectMask2D>()!=null||r.GetComponent<UnityEngine.UI.Mask>()!=null}})).ToString();}}
